CREATE TABLE service_plan_limits(plan_id TEXT PRIMARY KEY REFERENCES service_plans(id),limits_json TEXT NOT NULL);
CREATE TABLE email_verifications(user_id TEXT PRIMARY KEY REFERENCES users(id),token_hash TEXT NOT NULL,expires_at BIGINT NOT NULL,verified_at BIGINT);
CREATE TABLE email_jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),ciphertext TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,claimed_at BIGINT,error TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL);
CREATE INDEX email_job_due ON email_jobs(state,next_attempt);
CREATE TABLE deletion_jobs(id TEXT PRIMARY KEY,tenant_id TEXT,requester_id TEXT,scope TEXT NOT NULL CHECK(scope IN ('user','tenant','account','accounts')),targets TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',phase TEXT NOT NULL DEFAULT 'remote',remote_ciphertext TEXT NOT NULL DEFAULT '',remote_status TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,completed_at BIGINT,source_key TEXT UNIQUE);
CREATE INDEX deletion_due ON deletion_jobs(state,next_attempt);
CREATE TABLE deletion_objects(job_id TEXT NOT NULL REFERENCES deletion_jobs(id),object_key TEXT NOT NULL,PRIMARY KEY(job_id,object_key));
CREATE TABLE meta_read_watermarks(account_id TEXT NOT NULL REFERENCES service_accounts(id),peer_id TEXT NOT NULL,watermark_ms BIGINT NOT NULL,PRIMARY KEY(account_id,peer_id));
CREATE TABLE meta_data_connections(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL CHECK(kind IN ('catalogs','leads','marketing')),provider_id TEXT NOT NULL,label TEXT NOT NULL,api_version TEXT NOT NULL,ciphertext TEXT NOT NULL,app_id TEXT NOT NULL,subject_hash TEXT NOT NULL,scopes TEXT NOT NULL,expires_at BIGINT,state TEXT NOT NULL DEFAULT 'connected',last_sync BIGINT,error TEXT NOT NULL DEFAULT '',UNIQUE(kind,provider_id),UNIQUE(id,tenant_id));
CREATE TABLE meta_data_sessions(state_hash TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES users(id),session_hash TEXT NOT NULL,kind TEXT NOT NULL,app_id TEXT NOT NULL,config_id TEXT NOT NULL,api_version TEXT NOT NULL,expires_at BIGINT NOT NULL,stage TEXT NOT NULL DEFAULT 'started',ciphertext TEXT NOT NULL DEFAULT '',subject_hash TEXT NOT NULL DEFAULT '');
CREATE TABLE meta_data_records(connection_id TEXT NOT NULL,tenant_id TEXT NOT NULL,record_id TEXT NOT NULL,kind TEXT NOT NULL,ciphertext TEXT NOT NULL,synced_at BIGINT NOT NULL,PRIMARY KEY(connection_id,kind,record_id),FOREIGN KEY(connection_id,tenant_id) REFERENCES meta_data_connections(id,tenant_id));
CREATE TABLE meta_lead_events(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL,tenant_id TEXT NOT NULL,lead_id TEXT NOT NULL,created_at BIGINT NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',FOREIGN KEY(connection_id,tenant_id) REFERENCES meta_data_connections(id,tenant_id),UNIQUE(connection_id,lead_id));
CREATE INDEX email_verification_token ON email_verifications(token_hash);
CREATE INDEX meta_data_tenant ON meta_data_connections(tenant_id,state);
CREATE INDEX meta_data_subject ON meta_data_connections(app_id,subject_hash);
CREATE INDEX meta_lead_due ON meta_lead_events(state,next_attempt);
CREATE INDEX meta_record_tenant ON meta_data_records(tenant_id,connection_id);
CREATE INDEX meta_data_session_user ON meta_data_sessions(user_id);
INSERT INTO schema_migrations(version,applied_at) VALUES(10,'2026-11-18T00:00:00+00:00');
CREATE TABLE meta_page_posts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,account_id TEXT NOT NULL,author_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,payload_hash TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',remote_id TEXT,error TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,claimed_at BIGINT,created_at BIGINT NOT NULL,FOREIGN KEY(account_id,tenant_id) REFERENCES service_accounts(id,tenant_id),UNIQUE(tenant_id,request_key));
CREATE INDEX meta_post_due ON meta_page_posts(state,next_attempt);
CREATE TABLE worker_cursors(name TEXT PRIMARY KEY,position BIGINT NOT NULL);
